def fslmaths_outputs(params: Fslmaths, execution: Execution) -> FslmathsOutputs:
    """Build the FslmathsOutputs object for this tool."""
    root_v: OutputPathType = execution.output_file(".")
    output_file_v: OutputPathType = execution.output_file(params["output"])
    return FslmathsOutputs(
        root=root_v,
        output_file=output_file_v,
    )

def fslmaths_execute(params: Fslmaths, runner: Runner | None = None) -> FslmathsOutputs:
    """
    fslmaths

    FSL utility for image arithmetic, statistics, and mathematical operations

    Author: FMRIB Analysis Group, University of Oxford

    URL: https://fsl.fmrib.ox.ac.uk/fsl/fslwiki

    Args:
        params: The parameters.
        runner: Command runner (defaults to global runner).

    Returns:
        Tool outputs (paths to files produced by the tool).
    """
    fslmaths_validate(params)
    runner = runner if runner is not None else get_global_runner()
    execution = runner.start_execution(FSLMATHS_METADATA)
    execution.params(params)
    args = fslmaths_cargs(params, execution)
    out = fslmaths_outputs(params, execution)
    execution.run(args)
    return out

def fslmaths(
    input_files: list[InputPathType],
    operations: list[FslmathsOperations],
    output: str,
    datatype_internal: FslmathsDatatypeInternal | None = None,
    output_datatype: FslmathsDatatypeInternal | None = None,
    runner: Runner | None = None,
) -> FslmathsOutputs:
    """
    fslmaths

    FSL utility for image arithmetic, statistics, and mathematical operations

    Author: FMRIB Analysis Group, University of Oxford

    URL: https://fsl.fmrib.ox.ac.uk/fsl/fslwiki

    Args:
        input_files: Input images for processing
        operations: Operations to perform on input images
        output: Output image file
        datatype_internal: Datatype used internally for calculations
        output_datatype: Datatype used for the output image
        runner: Command runner (defaults to global runner).

    Returns:
        Tool outputs (paths to files produced by the tool).
    """
    params = fslmaths_params(
        input_files=input_files,
        operations=operations,
        output=output,
        datatype_internal=datatype_internal,
        output_datatype=output_datatype,
    )
    return fslmaths_execute(params, runner)

